//! Node's actual source/client matrix; keys are generated by a loopback fixture.
//! Native system stores are never read. Registered differences stay explicit.
#[path = "common/baseline.rs"]
mod baseline;
#[path = "common/exact_receipt.rs"]
mod exact_receipt;
#[path = "common/proxy_env.rs"]
mod proxy_env;
#[path = "common/scratch.rs"]
mod scratch;

use pilotdeck_gateway::runtime::{
    hooks::exec::{HttpHookExecutor, HttpHookOptions},
    mcp::{
        client::{McpClient, McpClientOptions},
        protocol::{McpServerSpec, McpTransportSpec},
    },
    model::{
        CountHttpRequest, HyperCountTransport, ProviderCountTransport,
        http::{HyperModelTransport, StreamOptions, complete_model},
    },
};
use pilotdeck_protocol::{JsObject, parse_json};
use serde_json::{Value, json};
use std::{path::Path, process::Stdio, time::Duration};
use tokio::io::AsyncBufReadExt;

const ORACLE: &str = include_str!("fixtures/private-ca/oracle.json");
const OPENSSL_CASES: &str = include_str!("fixtures/private-ca/openssl-cases.json");

async fn hook(url: &str) -> bool {
    HttpHookExecutor::new()
        .execute(HttpHookOptions {
            url: format!("{url}/hook").into(),
            headers: None,
            allowed_env_vars: None,
            hook_input: JsObject::new(),
            env: None,
            signal: None,
        })
        .await
        .outcome
        .as_str()
        == "success"
}

async fn child() {
    let url = std::env::var("PDRS_TLS_URL").expect("#1552 child test server URL");
    if std::env::var("PDRS_TLS_MODE").as_deref() == Ok("early-file") {
        std::fs::write(
            std::env::var_os("NODE_EXTRA_CA_CERTS").expect("#1552 child extra CA path"),
            std::fs::read(std::env::var_os("PDRS_TLS_RESTORE").expect("#1552 child restore path"))
                .expect("#1552 child restore bytes"),
        )
        .expect("#1552 child restores the empty extra CA file");
    }
    let client = McpClient::new(
        McpServerSpec {
            id: "tls".into(),
            transport: McpTransportSpec::StreamableHttp {
                url: format!("{url}/mcp"),
                headers: None,
            },
            call_timeout_ms: None,
        },
        McpClientOptions {
            handshake_timeout_ms: Some(1500.0),
            ..Default::default()
        },
    );
    let mcp = client.start().await.is_ok();
    client.close().await;
    let hook_ok = hook(&url).await;
    let config = parse_json(&json!({"providers":{"tls":{"id":"tls", "protocol":"anthropic",
        "url":url, "apiKey":"fixture-only", "models":{"probe":{"id":"probe", "capabilities":{"maxOutputTokens":32}, "multimodal":{"input":["text"]}}},
        "retry":{"requestMaxRetries":0}, "ca":std::fs::read_to_string(std::env::var_os("PDRS_TLS_CA").expect("#1552 child CA path")).expect("#1552 child CA bytes")}}}).to_string()).expect("#1552 child parses the provider config");
    let request = parse_json(r#"{"provider":"tls","model":"probe","messages":[{"role":"user","content":[{"type":"text","text":"local TLS test"}]}]}"#).unwrap();
    let model = complete_model(
        &HyperModelTransport::new(),
        &request,
        &config,
        &StreamOptions::default(),
    )
    .await
    .is_ok_and(|value| value.get("content").is_some());
    let count = HyperCountTransport::default()
        .post(CountHttpRequest {
            url: format!("{url}/v1/messages/count_tokens"),
            headers: JsObject::new(),
            body: request,
        })
        .await
        .is_ok_and(|value| value.get("input_tokens").and_then(|n| n.as_number()) == Some(7.0));
    let mut result = json!({"mcp":mcp,"hook":hook_ok,"model":model,"count":count});
    if std::env::var("PDRS_TLS_MODE").as_deref() == Ok("cached-file") {
        std::fs::write(
            std::env::var_os("NODE_EXTRA_CA_CERTS").expect("#1552 child cached extra path"),
            "",
        )
        .expect("#1552 child empties the cached extra CA file");
        result["cached"] = hook(&std::env::var("PDRS_TLS_FRESH").expect("#1552 child fresh URL"))
            .await
            .into();
    }
    std::fs::write(
        std::env::var_os("PDRS_TLS_RESULT").expect("#1552 child result path"),
        result.to_string(),
    )
    .expect("#1552 child writes the result cell");
}

#[tokio::test]
async fn private_ca_matrix() {
    if std::env::var_os("PDRS_TLS_URL").is_some() {
        tokio::time::timeout(Duration::from_secs(20), child())
            .await
            .expect("#1552 bounded client calls");
        return;
    }
    baseline::oracle(ORACLE);
    let oracle: Value = serde_json::from_str(ORACLE).expect("#1552 oracle JSON");
    let scratch = scratch::Scratch::new("private-ca");
    let mut server = tokio::process::Command::new("node")
        .arg(Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/private-ca/server.mjs"))
        .arg("--serve")
        .arg(scratch.path())
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .kill_on_drop(true)
        .spawn()
        .expect("#1552 node fixture server spawns");
    let mut lines =
        tokio::io::BufReader::new(server.stdout.take().expect("#1552 server stdout")).lines();
    let line = tokio::time::timeout(Duration::from_secs(30), lines.next_line())
        .await
        .expect("#1552 bounded server handshake")
        .expect("#1552 server stdout open")
        .expect("#1552 server prints its addresses");
    let addresses: Value = serde_json::from_str(&line).expect("#1552 server addresses JSON");
    let ca = scratch.path().join("ca.pem");
    let ca_bytes = std::fs::read(&ca).expect("#1552 generated CA bytes");
    let mut failures = Vec::new();
    let mut aligned = 0usize;
    let mut diverged = 0usize;
    let mut skipped = 0usize;
    // A6.4-TLS-CA-SOURCES-001-R1: `--use-openssl-ca` has no cells in the
    // frozen Homebrew oracle. These six cells were measured on the pinned
    // baseline (cc7c4e65 / Node v22.22.0 / linux) by `generate.mts` with
    // `PDRS_MODES=openssl-dir,openssl-file,openssl-plain`. The cells and their
    // provenance live in `fixtures/private-ca/openssl-cases.json`.
    // Same provenance guard as the frozen oracle: a wrong commit or an empty
    // hash table must fail here, not silently trust stale expectations.
    baseline::oracle(OPENSSL_CASES);
    let openssl: Value = serde_json::from_str(OPENSSL_CASES).expect("#1552 openssl cases JSON");
    let openssl_cases = openssl["cases"]
        .as_array()
        .expect("#1552 openssl cases array");
    assert_eq!(
        openssl_cases.len(),
        6,
        "#1552 measured --use-openssl-ca cell count"
    );
    let oracle_cases = oracle["cases"]
        .as_array()
        .expect("#1552 oracle cases array");
    assert_eq!(oracle_cases.len(), 56, "#1552 frozen oracle cell count");
    let mut cases: Vec<(String, bool, Value)> = oracle_cases
        .iter()
        .map(|case| {
            (
                case["mode"].as_str().expect("#1552 case mode").to_owned(),
                case["mismatch"].as_bool().expect("#1552 case mismatch"),
                case["expected"].clone(),
            )
        })
        .collect();
    for case in openssl_cases {
        cases.push((
            case["mode"]
                .as_str()
                .expect("#1552 openssl case mode")
                .to_owned(),
            case["mismatch"]
                .as_bool()
                .expect("#1552 openssl case mismatch"),
            case["expected"].clone(),
        ));
    }
    for (mode, mismatch, mut expected) in cases {
        // Node-only in-process environment mutation cannot be performed safely
        // in Rust 2024. Startup timing difference is recorded in the ledger.
        if mode == "late-env" {
            skipped += 1;
            continue;
        }
        std::fs::write(&ca, &ca_bytes).expect("#1552 reset generated CA");
        let result_path = scratch.path().join(format!("{mode}-{mismatch}.json"));
        let mut command = tokio::process::Command::new(
            std::env::current_exe().expect("#942 private-ca test binary path"),
        );
        command
            .args([
                "--exact",
                "private_ca_matrix",
                "--nocapture",
                "--test-threads=2",
            ])
            .env(
                "PDRS_TLS_URL",
                addresses[if mode.starts_with("proxy-") {
                    "target"
                } else if mismatch {
                    "bad"
                } else {
                    "good"
                }]
                .as_str()
                .expect("#1552 target address"),
            )
            .env("PDRS_TLS_RESTORE", scratch.path().join("initial-ca.pem"))
            .env("PDRS_TLS_CA", &ca)
            .env(
                "PDRS_TLS_FRESH",
                addresses[if mismatch { "freshBad" } else { "freshGood" }]
                    .as_str()
                    .expect("#1552 fresh address"),
            )
            .env("PDRS_TLS_MODE", &mode)
            .env("PDRS_TLS_RESULT", &result_path)
            .kill_on_drop(true)
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        for key in proxy_env::PROXY_ENV_KEYS.into_iter().chain([
            "NODE_EXTRA_CA_CERTS",
            "NODE_OPTIONS",
            "NODE_USE_SYSTEM_CA",
            "NODE_TLS_REJECT_UNAUTHORIZED",
            "SSL_CERT_FILE",
            "SSL_CERT_DIR",
        ]) {
            command.env_remove(key);
        }
        if [
            "extra",
            "early-file",
            "cached-file",
            "system-extra",
            "proxy-extra",
        ]
        .contains(&mode.as_str())
        {
            command.env("NODE_EXTRA_CA_CERTS", &ca);
        }
        if [
            "bundle",
            "partial",
            "missing",
            "empty",
            "bad",
            "other",
            "bad-first",
            "bad-der",
        ]
        .contains(&mode.as_str())
        {
            command.env(
                "NODE_EXTRA_CA_CERTS",
                scratch.path().join(format!("{mode}.pem")),
            );
        }
        if mode.starts_with("system-")
            || ["ssl-unflagged", "forced-bundled", "bundled-system"].contains(&mode.as_str())
        {
            command
                .env("SSL_CERT_FILE", &ca)
                .env("SSL_CERT_DIR", scratch.path().join("empty-dir"));
        }
        if [
            "system-empty",
            "system-dir",
            "dir-unflagged",
            "dir-plain",
            "openssl-dir",
            "openssl-plain",
        ]
        .contains(&mode.as_str())
        {
            command.env("SSL_CERT_FILE", scratch.path().join("empty.pem"));
        }
        if ["system-dir", "dir-unflagged", "openssl-dir"].contains(&mode.as_str()) {
            command.env("SSL_CERT_DIR", scratch.path().join("cert-dir"));
        }
        if mode == "dir-plain" || mode == "openssl-plain" {
            command.env("SSL_CERT_DIR", scratch.path().join("plain-dir"));
        }
        if mode.starts_with("system-") && mode != "system-off" {
            command.env("NODE_USE_SYSTEM_CA", "1");
        }
        if mode == "forced-bundled" {
            command.env("NODE_OPTIONS", "--use-bundled-ca");
        }
        if mode == "bundled-system" {
            command.env("NODE_OPTIONS", "--use-bundled-ca --use-system-ca");
        }
        // The oracle generated `system-options` with
        // `NODE_OPTIONS=--use-system-ca`; replay the same carrier.
        // `system-flag` passes a CLI flag, which a non-Node process cannot see.
        if mode == "system-options" {
            command.env("NODE_OPTIONS", "--use-system-ca");
        }
        if mode == "openssl-file" {
            command
                .env("SSL_CERT_FILE", &ca)
                .env("SSL_CERT_DIR", scratch.path().join("empty-dir"));
        }
        if mode.starts_with("openssl-") {
            command.env("NODE_OPTIONS", "--use-openssl-ca");
        }
        if mode.starts_with("proxy-") {
            command.env(
                "PILOTDECK_PROXY",
                addresses[if mismatch { "badProxy" } else { "proxy" }]
                    .as_str()
                    .expect("#1552 proxy address"),
            );
        }
        if mode == "early-file" {
            std::fs::write(&ca, "").expect("#1552 empties the extra CA file before the child");
        }
        let output = tokio::time::timeout(Duration::from_secs(30), command.output())
            .await
            .expect("#942 private-ca child bounded")
            .expect("#942 private-ca child collect");
        // #942: exit 0 alone is not a receipt — a renamed `private_ca_matrix`
        // makes this `--exact` filter match nothing and libtest still exits 0.
        assert!(
            exact_receipt::single_pass(
                &output.status,
                "private_ca_matrix",
                &String::from_utf8_lossy(&output.stdout)
            ),
            "#942 private-ca rerun matched no test: {mode}:\n{}",
            String::from_utf8_lossy(&output.stderr)
        );
        let actual: Value = serde_json::from_str(
            &std::fs::read_to_string(result_path).expect("#1552 result cell readable"),
        )
        .expect("#1552 result cell JSON");
        // A6.4-TLS-CA-SOURCES-001-R1 / issue #1640: the frozen Homebrew oracle
        // and the project baseline (Node v22.22.0 source build, cc7c4e65)
        // disagree on these cells and the口径 is not decided yet. Rust follows
        // the frozen oracle for `dir-unflagged` and the source build for
        // `early-file`; neither is counted as parity. `system-dir` is not here:
        // the source build measured all-true on cb8 (logs/gen-modes-cb8.log),
        // the same as the frozen oracle and as Rust.
        let difference = ["dir-unflagged", "early-file"].contains(&mode.as_str());
        let ts_oracle = expected.clone();
        if difference && !mismatch {
            for value in expected
                .as_object_mut()
                .expect("#1552 expected object")
                .values_mut()
            {
                *value = json!(true);
            }
        }
        if difference {
            diverged += 1;
        } else {
            aligned += 1;
        }
        println!(
            "{mode} mismatch={mismatch} actual={actual} TS_oracle={ts_oracle} \
             registered_difference={difference}"
        );
        if actual != expected {
            failures.push(format!(
                "{mode}/{mismatch}: actual={actual} expected={expected}"
            ));
        }
    }
    server.stdin.take();
    tokio::time::timeout(Duration::from_secs(5), server.wait())
        .await
        .expect("#1552 bounded server shutdown")
        .expect("#1552 node fixture server exits");
    // The matrix proves how many cells actually ran: an empty or truncated
    // `cases` array must not pass silently.
    assert_eq!(skipped, 2, "#1552 only the two late-env cells are skipped");
    assert_eq!(
        diverged, 4,
        "#1552 registered differences are two modes x two hostnames"
    );
    assert_eq!(
        aligned, 56,
        "#1552 aligned cells: 56 frozen - 2 late-env - 4 registered differences + 6 openssl"
    );
    assert!(
        failures.is_empty(),
        "#1552 private CA source matrix diverges:\n{}",
        failures.join("\n")
    );
}
